/* 🌟 Bento Grid Layout */
.bento-container {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  width: 100%;
  max-width: 520px;
}

.bento-item {
  background: #151f34;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 18px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  transition: all 0.25s ease;
}

.bento-item:hover {
  border-color: rgba(56, 189, 248, 0.4);
  transform: translateY(-2px);
}

.featured {
  grid-column: span 2;
  background: linear-gradient(135deg, #151f34 0%, #0d1627 100%);
  border-color: rgba(56, 189, 248, 0.25);
  position: relative;
  overflow: hidden;
}

.featured::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 150px;
  height: 150px;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.15) 0%, transparent 70%);
}

