/* 🌟 Dynamic color-mix in modern perceptual OKLCH color space */
.s-base {
  background: var(--c1);
}

.s-25 {
  background: color-mix(in oklch, var(--c1) 75%, var(--c2) 25%);
}

.s-50 {
  background: color-mix(in oklch, var(--c1) 50%, var(--c2) 50%);
}

.s-75 {
  background: color-mix(in oklch, var(--c1) 25%, var(--c2) 75%);
}

.s-target {
  background: var(--c2);
  color: #ffffff;
}

