/* 1. Define container context */
.card-container {
  container-type: inline-size;
  container-name: cardbox;
}

/* Base Card Style (Vertical layout for small container) */
.card {
  display: flex;
  flex-direction: column;
  background: #1e293b;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.3s ease;
}

.card-media {
  background: linear-gradient(135deg, #0284c7, #38bdf8);
  font-size: 3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 120px;
}

.card-content {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.badge {
  align-self: flex-start;
  background: rgba(56, 189, 248, 0.2);
  color: #38bdf8;
  font-size: 0.72rem;
